import re

def parse_comp(s):
    s = s.replace('$', '').lower()
    num_pattern = r'(\d+([,.]\d*)*|\d*k)'
    matches = re.findall(num_pattern, s)
    if not matches:
        return None
    nums = []
    for m in matches:
        m = m.replace(',', '')
        if m.endswith('k'):
            nums.append(int(m[:-1]) * 1000)
        else:
            nums.append(int(m))
    if len(nums) == 1:
        return [nums[0], nums[0]]
    elif len(nums) >= 2:
        # Check if the numbers are in a range
        range_pattern = re.compile(r'\d+\D*\d+')
        if range_pattern.match(''.join(map(str, nums))):
            return sorted(nums)
        else:
            return None
    else:
        return None

