import re

def parse_comp(s):
    num_pattern = r'\$?\d[\d,.]*[kK]?$'  # Matches numbers with optional $, commas, and k/K
    nums = re.findall(num_pattern, s)
    nums = [float(n.replace('$', '').replace(',', '').replace('k', '').replace('K', ''))
            for n in nums]

    # Handle ranges
    if len(nums) >= 2:
        # Check for range indicators
        range_words = ['to', '-', '–']
        for word in range_words:
            if word in s:
                try:
                    low = min(nums)
                    high = max(nums)
                    return [int(low), int(high)]
                except:
                    return None
        # If no range indicator, return the two numbers as [low, high]
        return [int(min(nums)), int(max(nums))]
    elif len(nums) == 1:
        return [int(nums[0]), int(nums[0])]
    else:
        return None

