import re

def parse_comp(s):
    s = s.replace('$', '').lower()
    nums = re.findall(r'\d+\.?\d*|\d+|\d+k', s)
    nums = [int(n.replace('k', '').replace(',', '')) * 1000 if n.endswith('k') else int(n.replace(',', '')) for n in nums]
    nums = [x for x in nums if x > 0]
    if len(nums) < 1:
        return None
    if len(nums) == 1:
        return [nums[0], nums[0]]
    nums.sort()
    for i in range(len(nums)-1, 0, -1):
        if nums[i] < nums[i-1]:
            nums.pop(i)
    if len(nums) >= 2:
        return [nums[0], nums[-1]]
    return None
